      "rank": 5,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Bart J. van Wees",
        "Henk van Houten",
        "Michael Pepper"
      ],
      "assessment": {
        "nobel_worthiness": "Conductance quantization made quantum transport in an electronic nanostructure directly visible and opened modern mesoscopic physics.",
        "attribution": "The listed scientists represent pivotal experimental discoveries and development of ballistic point-contact transport.",
        "maturity": "The quantized conductance steps are robust, routinely reproduced, and have become a textbook quantum phenomenon.",
        "uncertainties": [
          "Priority and the appropriate balance between closely contemporaneous experimental groups need detailed review."
        ]
      }
    },
    {
      "rank": 6,
